S=/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad; python3 explorations/coordinator/tools/ledger.py heads > $S/heads.tsv; sed -n '25,256p' explorations/coordinator/review-queue.md | grep '^- \*\*[0-9]' > $S/summary.txt; wc -l $S/summary.txt; python3 - <<'EOF'
import re
S='/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad'
st={}
for l in open(S+'/heads.tsv'):
    p=l.split('\t'); st[p[0]]=p[1]
closed={'FIXED','RETIRED','DUPLICATE'}
for l in open(S+'/summary.txt'):
    n=re.match(r'- \*\*(\d+)',l).group(1)
    rows=set()
    for m in re.finditer(r'rows? ((?:\d+(?:, | and |, and )?)+)',l):
        rows|=set(re.findall(r'\d+',m.group(1)))
    c=[(r,st.get(r,'?')) for r in sorted(rows,key=int)]
    if any(s in closed for r,s in c): print(n,c)
EOF

